import { createHash } from "node:crypto";
import { spawn, spawnSync } from "node:child_process";
import { mkdirSync, writeFileSync, readFileSync, existsSync, cpSync, appendFileSync, rmSync } from "node:fs";
import { join, resolve } from "node:path";
import { Database } from "bun:sqlite";
const root = process.env.ISSUE824_ROOT!;
for (const key of ["HOME", "XDG_DATA_HOME", "XDG_CONFIG_HOME", "XDG_STATE_HOME", "XDG_RUNTIME_DIR", "XDG_CACHE_HOME", "TMPDIR", "MAGIC_CONTEXT_STORAGE_DIR"]) {
    const path = join(root, "harness", key); mkdirSync(path, { recursive: true, mode: 0o700 }); process.env[key] = path;
}
process.env.CFFIXED_USER_HOME = process.env.HOME;
process.env.OPENCODE_DB = "harness.db";
const { OpenCode } = await import(Bun.resolveSync("@opencode/client", resolve("packages/e2e-tests")));
const { V2StoreReader } = await import("../../packages/plugin/src/v2/store-reader");
const { rawMessages, createV2RawMessageReader, createV2RawMessageProvider } = await import("../../packages/plugin/src/v2/hooks/store");
const { setBoundedRawMessageProvider } = await import("../../packages/plugin/src/hooks/magic-context/read-session-chunk");
const { renderItemByTag } = await import("../../packages/plugin/src/tools/ctx-expand/render");
const { setHarness } = await import("../../packages/plugin/src/shared/harness");
setHarness("opencode2");
const { estimateTokens, preloadTokenizer } = await import("../../packages/plugin/src/hooks/magic-context/read-session-formatting");
await preloadTokenizer();
import { MockProvider } from "../../packages/e2e-tests/src/mock-provider/server";

const cli = process.env.MC_E2E_OPENCODE2_CLI!;
const mode = process.argv[2] ?? "baseline";
const run = join(root, mode);
mkdirSync(run, { recursive: true });
const results: any = { mode, root, checks: [] };
const save = () => writeFileSync(join(root, mode + ".json"), JSON.stringify(results, null, 2));
const check = (label: string, condition: unknown) => { results.checks.push({ label, passed: Boolean(condition) }); save(); if (!condition) throw new Error(label); };
const size = (value: unknown) => Buffer.byteLength(typeof value === "string" ? value : JSON.stringify(value));
const mock = new MockProvider();
const { baseURL } = await mock.start();
let n = 0;
let building = false;
let rejectLarge = false;
let reportedInput = 100;
let capturePhase = "warmup";
mock.addMatcher((body) => {
    const text = JSON.stringify(body);
    if (rejectLarge && estimateTokens(text) > 21000) {
        (results.rejections ??= []).push({ phase: capturePhase, tokens: estimateTokens(text), limit: 21000 });
        return { error: { status: 400, type: "invalid_request_error", message: `prompt is too long: ${estimateTokens(text)} tokens > 21000 maximum` } };
    }
    if (building && n === 6) {
        const reader = new V2StoreReader(dbPath());
        const rows = rawMessages(reader.history(sid)); reader.close();
        const end = rows.at(-2)!;
        const covered = rows.slice(0, -1);
        const markers = [...new Set(JSON.stringify(covered).match(/TOOL-ROW-\d+/g) ?? [])];
        const summary = `Completed generated evidence: ${markers.join(" ")}.`;
        const db = new Database(join(runtime, "mc/context.db"));
        db.query("INSERT INTO compartments (session_id,sequence,start_message,end_message,start_message_id,end_message_id,title,content,p1,created_at,harness) VALUES (?,1,?,?,?,?,'Published history fixture',?,?,?,'opencode2')").run(sid, rows[0]!.ordinal, end.ordinal, rows[0]!.id, end.id, summary, summary, Date.now());
        db.query("UPDATE session_meta SET cached_m0_model_key='fixture/previous-model' WHERE session_id=?").run(sid); db.close();
        results.summaryFixture = { endID: end.id, endOrdinal: end.ordinal, summary, covered: covered.map(row => row.id) };
    }
    if (building && n++ < 12) return { content: [{ type: "tool_use", id: `call_${n}`, name: "shell", input: { command: `python3 -c 'print("TOOL-ROW-${n} " + "historical evidence boundary context " * 350)'` + (n === 1 ? " # " + "raw-input-checkpoint-padding ".repeat(3000) : "") } }], stop_reason: "tool_use", usage: { input_tokens: 100, output_tokens: 30 } };
    return { text: "done", usage: { input_tokens: reportedInput, output_tokens: 10 } };
});
mock.setDefault({ text: "done", usage: { input_tokens: 100, output_tokens: 10 } });
let child: ReturnType<typeof spawn> | undefined;
let client: any;
let runtime = join(run, "runtime");
let sid: string;
let firstUser: string | undefined;
let cwd = join(runtime, "work");
const paths = ["home", "config", "data", "state", "cache", "runtime", "tmp", "mc", "work"];
if (mode === "recovery" || mode === "priced") {
    runtime = join(root, "baseline/runtime");
    rmSync(runtime, { recursive: true, force: true });
    cpSync(join(root, "legacy-runtime"), runtime, { recursive: true });
    sid = JSON.parse(readFileSync(join(root, "baseline.json"), "utf8")).sessionID;
} else sid = "";
cwd = join(runtime, "work");
for (const name of paths) mkdirSync(join(runtime, name), { recursive: true, mode: 0o700 });
const env = { PATH: process.env.PATH!, HOME: join(runtime, "home"), CFFIXED_USER_HOME: join(runtime, "home"), XDG_CONFIG_HOME: join(runtime, "config"), XDG_DATA_HOME: join(runtime, "data"), XDG_STATE_HOME: join(runtime, "state"), XDG_CACHE_HOME: join(runtime, "cache"), XDG_RUNTIME_DIR: join(runtime, "runtime"), TMPDIR: join(runtime, "tmp"), OPENCODE_DB: "issue824.db", OPENCODE_DISABLE_DEFAULT_PLUGINS: "true", OPENCODE_DISABLE_AUTOUPDATE: "true", OPENCODE_DISABLE_MODELS_FETCH: "true", MAGIC_CONTEXT_STORAGE_DIR: join(runtime, "mc"), MAGIC_CONTEXT_LOG_PATH: join(run, "mc.log"), MAGIC_CONTEXT_LOG_SYNC: "1" };
const version = spawnSync(cli, ["--version"], { env, encoding: "utf8" });
results.version = version.stdout.trim();
check("real pinned host version", version.status === 0 && results.version === "opencode v2.2.2");
const probe = (label: string) => {
    const dir = join(run, label); mkdirSync(dir, { recursive: true });
    writeFileSync(join(dir, "server.js"), `import {appendFileSync} from 'node:fs'; export default {id:'issue824-${label}',async setup(ctx){await ctx.agent.transform(e=>e.update('build',a=>{a.permissions=[{action:'*',resource:'*',effect:'allow'}]})); await ctx.agent.reload(); for(const kind of ['compaction','context']) await ctx.session.hook(kind, d=>{appendFileSync(${JSON.stringify(join(run, label + ".jsonl"))}, JSON.stringify({kind,sessionID:d.sessionID,messages:d.messages,result:d.result})+'\\n');});}}`);
    return dir;
};
const pre = probe("before"); const post = probe("after");
const mcPlugin = join(root, "shared-mc-plugin"); mkdirSync(mcPlugin, { recursive: true });
writeFileSync(join(mcPlugin, "server.js"), `export {default} from ${JSON.stringify(resolve("packages/plugin/dist/v2/server.js"))};`);
const window = mode === "priced" ? 200000 : 21000;
writeFileSync(join(cwd, "opencode.json"), JSON.stringify({ plugins: [pre, mcPlugin, post], model: "anthropic/mock", compaction: { auto: false, keep: { tokens: 1024 } }, providers: { anthropic: { settings: { baseURL, apiKey: "fixture" }, models: { mock: { name: "mock", compaction: { mode: "provider" }, limit: { context: window, output: 1024 } } } } } }));
mkdirSync(join(runtime, "config/cortexkit"), { recursive: true });
writeFileSync(join(runtime, "config/cortexkit/magic-context.jsonc"), JSON.stringify({ auto_update: false, historian: { disable: true }, dreamer: { disable: true }, memory: { enabled: false }, embedding: { provider: "off" }, cache_ttl: "never" }));
const start = async () => {
    child = spawn(cli, ["serve", "--hostname", "127.0.0.1", "--port", "0", "--print-logs"], { cwd, env, detached: true, stdio: ["ignore", "pipe", "pipe"] });
    let out = "", err = "";
    child.stderr!.on("data", d => { err += d; appendFileSync(join(run, "host.log"), d); });
    const ready: any = await new Promise((ok, fail) => {
        const t = setTimeout(() => fail(new Error("startup timeout " + err.slice(-5000))), 60000);
        child!.stdout!.on("data", d => { out += d; const url = out.match(/https?:\/\/127\.0\.0\.1:\d+/)?.[0]; const password = out.match(/server password (\S+)/)?.[1]; if (url && password) { clearTimeout(t); ok({ url, password }); } });
        child!.on("exit", code => { clearTimeout(t); fail(new Error("host exited " + code + err)); });
    });
    client = OpenCode.make({ baseUrl: ready.url, headers: { authorization: `Basic ${btoa(`opencode:${ready.password}`)}` } });
    await client.location.get({ location: { directory: cwd } });
    const { awaitPluginActivation } = await import("../../packages/e2e-tests/src/opencode2-runner/plugin-activation");
    await awaitPluginActivation(client, cwd, "@cortexkit/opencode-magic-context");
    const lsof = spawnSync(process.env.ISSUE824_LSOF ?? "/usr/bin/lsof", ["-p", String(child.pid)], { encoding: "utf8" });
    if (lsof.error || !lsof.stdout) throw new Error(`lsof failed: ${lsof.error} status=${lsof.status} stderr=${lsof.stderr}`);
    writeFileSync(join(run, `lsof-${Date.now()}.txt`), lsof.stdout);
    const dbs = lsof.stdout.split("\n").filter(s => /\.db(?:\b|[- ])/.test(s));
    results.databases = dbs;
    check("all open databases inside throwaway root", lsof.status === 0 && dbs.length > 0 && dbs.every(s => s.includes(runtime)));
};
const stop = async () => { if (child?.pid && child.exitCode === null) { const exited = new Promise(ok => child!.once("exit", ok)); process.kill(-child.pid, "SIGKILL"); await exited; } child = undefined; };
const dbPath = () => join(runtime, "data/opencode/issue824.db");
const compaction = () => { const db = new Database(dbPath(), { readonly: true }); try { return db.query("SELECT * FROM session_message WHERE session_id=? AND type='compaction' ORDER BY seq DESC LIMIT 1").get(sid) as any; } finally { db.close(); } };
const kv = () => { const db = new Database(dbPath(), { readonly: true }); try { return db.query("SELECT * FROM kv WHERE key LIKE ?").all(`%fold/v1/${sid}`); } finally { db.close(); } };
const turn = async (text: string) => {
    const before = mock.requests().length;
    await client.session.prompt({ sessionID: sid, text });
    await client.session.wait({ sessionID: sid }, { signal: AbortSignal.timeout(90000) });
    for (const [i, req] of mock.requests().slice(before).entries()) {
        const path = join(run, `${capturePhase}-${i}.request.json`);
        writeFileSync(path, req.rawBody!);
        const wire = req.rawBody!;
        const summary = wire.match(/<summary>([\s\S]*?)<\/summary>/)?.[1] ?? "";
        const recent = wire.match(/<recent-context>([\s\S]*?)<\/recent-context>/)?.[1] ?? "";
        (results.requests ??= []).push({ phase: capturePhase, path, bytes: size(wire), approxTokens: estimateTokens(wire), summaryWireBytes: size(summary), recentWireBytes: size(recent), systemJSONBytes: size(req.body.system ?? []), toolDefinitionsJSONBytes: size(req.body.tools ?? []), recent: recent.length > 0, markers: Array.from({ length: 12 }, (_, j) => wire.includes(`TOOL-ROW-${j + 1}`)) });
    }
    if (existsSync(join(runtime, "mc/context.db"))) {
        const db = new Database(join(runtime, "mc/context.db"), { readonly: true });
        const meta = db.query("SELECT * FROM session_meta WHERE session_id=?").get(sid) as any; db.close();
        (results.usage ??= []).push({ phase: capturePhase, ...Object.fromEntries(Object.entries(meta ?? {}).filter(([k]) => /input_tokens|context_percentage|conversation_tokens|tool_call_tokens|system_prompt_tokens/.test(k))) });
    }
    save();
};
try {
    await start();
    if (mode === "baseline" || mode === "fixed") {
        const session = await client.session.create({ location: { directory: cwd }, title: "issue 824 long agent", model: { providerID: "anthropic", id: "mock" } });
        sid = session.id; results.sessionID = sid;
        capturePhase = "setup"; await turn("Initialize the project before the long agent run.");
        capturePhase = "warmup"; building = true; await turn("Build the long agent history using tools."); building = false;
        const db = new Database(dbPath(), { readonly: true }); firstUser = (db.query("SELECT id FROM session_message WHERE session_id=? AND type='user' ORDER BY seq DESC LIMIT 1").get(sid) as any)?.id; db.close();
        capturePhase = "compaction";
        await client.session.compact({ sessionID: sid }); await client.session.wait({ sessionID: sid }, { signal: AbortSignal.timeout(60000) });
        results.compactionRow = compaction();
        check("host completed the hooked compaction", JSON.parse(results.compactionRow.data).status === "completed");
        rejectLarge = mode === "fixed";
        for (let i = 0; i < 3; i++) {
            capturePhase = `post-${i}`; await turn(`Continue ${i}`);
            if (mode === "baseline" && i === 0) {
                await stop(); cpSync(runtime, join(root, "legacy-runtime"), { recursive: true }); await start();
                rejectLarge = true;
            }
        }
        results.foldRows = kv(); save();
        if (mode === "fixed") {
            const data = JSON.parse(results.compactionRow.data);
            check("stored compaction has no keepID", !Object.hasOwn(data.metadata ?? {}, "keepID"));
            check("three requests have no recent-context", results.requests.filter((r: any) => r.phase.startsWith("post-")).length === 3 && results.requests.filter((r: any) => r.phase.startsWith("post-")).every((r: any) => !r.recent));
            check("all pre-cut tool markers survive", results.requests.filter((r: any) => r.phase.startsWith("post-")).every((r: any) => r.markers.every(Boolean)));
        } else {
            check("baseline host recent-context reproduced", results.requests.some((r: any) => r.phase === "post-0" && r.recent));
            capturePhase = "post-3"; await turn("Continue 3");
            check("three consecutive over-window requests were rejected", results.rejections.filter((r: any) => ["post-1", "post-2", "post-3"].includes(r.phase)).length === 3);
            await stop(); await start();
            results.revertAPI = Object.keys(client.session);
            await client.session.revert.stage({ sessionID: sid, messageID: firstUser });
            await client.session.revert.commit({ sessionID: sid });
            capturePhase = "revert"; await turn("Continue after revert");
            results.revertedCompaction = compaction(); results.revertedFold = kv();
            await stop();
            const store = new Database(dbPath()); results.deleted = store.query("DELETE FROM kv WHERE key LIKE ?").run(`%fold/v1/${sid}`); store.close();
            await start(); capturePhase = "delete-fold"; await turn("Continue after deleting fold entry");
            await stop(); rmSync(runtime, { recursive: true, force: true });
            cpSync(join(root, "legacy-runtime"), runtime, { recursive: true });
            const original = new Database(dbPath());
            original.query("DELETE FROM kv WHERE key LIKE ?").run(`%fold/v1/${sid}`); original.close();
            await start(); capturePhase = "delete-only-unreverted"; await turn("Continue with the host compaction row but no plugin fold entry");
            results.deleteOnlyCompaction = compaction(); results.deleteOnlyFold = kv();
            check("deleting only KV cannot remove the host recent-context", results.requests.some((r: any) => r.phase === "delete-only-unreverted" && r.recent));
        }
    } else {
        const snapshot = () => {
            const reader = new V2StoreReader(dbPath());
            try { return rawMessages(reader.history(sid)); } finally { reader.close(); }
        };
        const beforeRows = snapshot();
        writeFileSync(join(run, "source-before.json"), JSON.stringify(beforeRows));
        const before = beforeRows.map(row => ({ id: row.id, ordinal: row.ordinal, sha256: createHash("sha256").update(JSON.stringify(row)).digest("hex") }));
        if (mode === "priced") {
            reportedInput = 140000; capturePhase = "prime-priced"; await turn("Prime the ordinary priced pass"); reportedInput = 100;
            const db = new Database(join(runtime, "mc/context.db"));
            db.query("UPDATE session_meta SET cached_m0_model_key='fixture/previous-model' WHERE session_id=?").run(sid); db.close();
        }
        rejectLarge = mode === "recovery";
        capturePhase = mode === "recovery" ? "upgrade" : "priced";
        await turn("First upgraded request must fit without a provider overflow");
        for (let i = 0; i < 3; i++) { capturePhase = `stable-${i}`; await turn(`Continue after checkpoint repair ${i}`); }
        results.foldRows = kv();
        const repaired = results.requests.filter((r: any) => r.phase === (mode === "recovery" ? "upgrade" : "priced"));
        check("first upgraded request strips recent-context and fits", repaired.length === 1 && repaired.every((r: any) => !r.recent && r.approxTokens <= window));
        if (mode === "priced") check("ordinary priced strip preserves every tool marker on wire", repaired.every((r: any) => r.markers.every(Boolean)));
        const oldIDs = new Set(before.map(row => row.id));
        const afterRows = snapshot().filter(row => oldIDs.has(row.id));
        writeFileSync(join(run, "source-after.json"), JSON.stringify(afterRows));
        const after = afterRows.map(row => ({ id: row.id, ordinal: row.ordinal, sha256: createHash("sha256").update(JSON.stringify(row)).digest("hex") }));
        results.sourceRows = { before, after };
        check("every pre-upgrade raw row survives byte-identically", JSON.stringify(before) === JSON.stringify(after));
        const db = new Database(join(runtime, "mc/context.db"), { readonly: true });
        const tags = db.query("SELECT tag_number,status FROM tags WHERE session_id=? AND type='tool'").all(sid) as any[];
        const release = setBoundedRawMessageProvider(sid, createV2RawMessageProvider(createV2RawMessageReader(() => new V2StoreReader(dbPath())), sid));
        let expanded: any[];
        try { expanded = tags.map(tag => ({ ...tag, text: renderItemByTag(db as never, sid, tag.tag_number) })); }
        finally { release(); db.close(); }
        writeFileSync(join(run, "ctx-expand-sources.json"), JSON.stringify(expanded));
        results.recoverable = Array.from({ length: 7 }, (_, i) => ({ marker: `TOOL-ROW-${i + 6}`, tags: expanded.filter(s => s.text.includes(`TOOL-ROW-${i + 6} `) && s.text.includes("historical evidence boundary context ".repeat(100))).map(s => ({ tag: s.tag_number, status: s.status })) }));
        check("all seven unsummarized outputs remain recoverable through ctx_expand's real renderer", results.recoverable.every((row: any) => row.tags.length > 0));
        const folded = JSON.parse(results.foldRows[0].value);
        check("pinned checkpoint has no recent text in content or metadata", !JSON.stringify(folded.rendered).includes("<recent-context>") && !Object.hasOwn(folded.rendered.metadata ?? {}, "recent"));
        const frames = readFileSync(join(run, "after.jsonl"), "utf8").trim().split("\n").map(line => JSON.parse(line)).filter(f => f.kind === "context");
        const heads = frames.slice(-4).map(f => JSON.stringify(f.messages[0]));
        check("repaired head byte stable for three defers", heads.length === 4 && new Set(heads).size === 1);
    }
} catch (e) { results.error = String(e); throw e; }
finally { save(); await stop(); await mock.stop(); console.log(JSON.stringify(results, null, 2).slice(0, 16000)); }

